func TestFindArtifactItemReturnsLastMatchingBlock(t *testing.T) {
	parsed := parseArtifactResponse(t, `{"steps":[
		{"type":"model_output","content":[{"type":"text","text":"draft"},{"type":"image","data":"Zmlyc3Q="}]},
		{"type":"model_output","content":[{"type":"image","data":"bGFzdA=="},{"type":"text","text":"done"}]}]}`)

	item := findArtifactItem(parsed, artifactTestConfig("image"))
	if item == nil {
		t.Fatal("expected an image block")
	}
	if got := item["data"]; got != "bGFzdA==" {
		t.Fatalf("data = %v, want the last image block", got)
	}
}

