func TestFindArtifactItemSelectsTrailingBlockWithoutData(t *testing.T) {
	for name, raw := range map[string]string{
		"missing": `{"steps":[{"content":[{"type":"image","data":"aW5saW5l"},{"type":"image"}]}]}`,
		"empty":   `{"steps":[{"content":[{"type":"image","data":"aW5saW5l"},{"type":"image","data":""}]}]}`,
	} {
		t.Run(name, func(t *testing.T) {
			parsed := parseArtifactResponse(t, raw)
			item := findArtifactItem(parsed, artifactTestConfig("image"))
			if item == nil {
				t.Fatal("expected the trailing image block")
			}
			if got := item["type"]; got != "image" {
				t.Fatalf("type = %v, want image", got)
			}
			if got, present := item["data"]; name == "missing" && present || name == "empty" && got != "" {
				t.Fatalf("data = %v (present %t), want the trailing %s data field", got, present, name)
			}
		})
	}
}

func TestArtifactExtensionNormalizesSubtype(t *testing.T) {
	cases := map[string]string{
		"image/png":                "png",
		"image/svg+xml":            "svg",
		"image/webp; q=0.9":        "webp",
		"audio/x-flac":             "flac",
		"audio/x-wav":              "wav",
		"image/x-icon":             "ico",
		"image/vnd.microsoft.icon": "ico",
	}
	for mime, want := range cases {
		kind, _, _ := strings.Cut(mime, "/")
		if got := artifactExtension(kind, mime); got != want {
			t.Errorf("artifactExtension(%q) = %q, want %q", mime, got, want)
		}
	}
	if got := artifactExtension("image", "audio/wav"); got != "" {
		t.Errorf("wrong-kind MIME resolved to %q", got)
	}
}

